-- Witch Hunt: the spirit witch drawn on every machine (client side). No #version line (included).
-- Needs "script/include/player.lua" and "wh_witch_rig.lua" (WH_RIG, generated by tools/make_witch.py) included
-- BEFORE this file. Only globals are shared with the including script (its locals are file-private). Globals:
--   whVisualTick(dt, spirits)  from client.render, every frame. spirits = list of
--                              {p = player, pose = "float" | "attack" | "stunned", t = seconds in this pose, smoke = bool}.
--                              Spawns one model per listed player (14 non-colliding parts), places it on the player
--                              every frame, poses it (float: hovering, leaning / streaming by the player's velocity;
--                              attack: a WV_ANIM.attack s claw strike with one arm, alternating; stunned: shielding the
--                              face, thrashing, convulsing, held as long as the pose lasts), blends between poses,
--                              trails wisps and a faint cold light, and deletes the models of players no longer listed.
--                              On the spirit's own machine her model is invisible (first person) except her striking
--                              claw during an attack. smoke = true: a few extra wisps (the game logic spawns the burst).
--   whVisualClear()            deletes every model (the round / mode ends).
--   whVisualBodies(p)          player p's model part bodies on this machine ({} without one).
--   WV_SHAPES                  every model part's shape on this machine (flat list, rebuilt when models come and
--                              go): reject them in raycasts (QueryRejectShapes) - on the host they share the scene.
--   WV_LAYER                   32: the parts' collision layer (mask 0: they collide with nothing). Keep it out of every
--                              player's CollisionMask (the game logic does), or players stand on the parts.
--   WVPose(a, out), WV_ANIM, WV_POSES   the pure pose maths (offline tests and the previews use them).
-- Every part body and shape is tagged "whwitch" (+ "unbreakable", "nocull").
-- This file does NOT hide the human body (the game logic calls SetPlayerHidden).
-- Pattern from Humans vs Clickers' monster_visual.lua (verified in-game): one dynamic body per part, collision
-- filtered off, SetBodyTransform + zero velocities from client.render, the scaled (0.5) parts' boxes measured and
-- centred on their body once the engine reports their size.

WV_LAYER = 32
WV_VOX_SCALE = 0.5          -- 0.05 m voxels (tools/make_witch.py)
WV_SHAPES = {}
WV_POSES = {"float", "attack", "stunned"}
WV_ANIM = {
	attack = 0.5,           -- s: the claw strike (wind-up to 0.14, strike to 0.28, recovery to 0.5)
	blendIn = 0.16,         -- s: cross-fade into float / stunned
	blendAttack = 0.06,     -- s: cross-fade into the strike (it must start at once)
	flySpeed = 9,           -- m/s at which she is fully streamlined (lean, robe and hair streaming, arms back)
	velSmooth = 0.22,       -- s: smoothing of the velocity that drives the lean
	wispRate = 26,          -- wisps per second near the camera (half beyond WV_ANIM.wispMid, none beyond wispFar)
	wispMid = 25, wispFar = 60,
	light = 0.9,            -- PointLight intensity (cold blue-white at her chest)
	selfLight = 3.5,        -- her own machine: a soft light at her head and ahead of her view (sees at night - the user)
	lift = 0.1,             -- m: the whole model floats this much above the sculpt (hem tips ~0.25 m above the ground)
}

-- ======================================================================== pose maths (pure: no engine state)
-- WVPose(a, out): fills out[partName] = Transform(centre, rot) = each part's .vox box CENTRE and rotation in the
-- witch's ROOT frame (origin = ground point under her centre, +y up, +z forward, +x = her left). Existing out
-- transforms are updated in place. a = {
--   wf, wa, ws   blend weights of float / attack / stunned (sum ~1)
--   ta           seconds into the attack;   side   1 = her left arm strikes, -1 = her right
--   ts           seconds stunned
--   vf, vs, vu   her velocity in her own frame (m/s): forward (+z), toward her left (+x), up
--   look         head pitch (radians, > 0 = looking up, like a camera pitch)
--   time, seed   GetTime() and a per-witch number (desynchronises several witches) }
-- Conventions: a part's local rotation is in its parent's frame about its own pivot. pitch (deg, about +x): positive
-- swings a hanging limb BACK and tips the top / face FORWARD-DOWN; yaw about +y: positive turns toward +x (her left);
-- roll about +z: positive moves a hanging limb toward +x.
do
	local sin, cos, abs, sqrt, floor, min, max, pi, exp = math.sin, math.cos, math.abs, math.sqrt, math.floor, math.min, math.max, math.pi, math.exp
	local RAD = pi / 180

	local function qmul(ax, ay, az, aw, bx, by, bz, bw)
		return aw * bx + ax * bw + ay * bz - az * by,
			aw * by - ax * bz + ay * bw + az * bx,
			aw * bz + ax * by - ay * bx + az * bw,
			aw * bw - ax * bx - ay * by - az * bz
	end
	local function qaxis(x, y, z, deg)
		local h = deg * RAD * 0.5
		local s = sin(h)
		return x * s, y * s, z * s, cos(h)
	end
	local function qrot(qx, qy, qz, qw, vx, vy, vz)
		local tx = 2 * (qy * vz - qz * vy)
		local ty = 2 * (qz * vx - qx * vz)
		local tz = 2 * (qx * vy - qy * vx)
		return vx + qw * tx + (qy * tz - qz * ty), vy + qw * ty + (qz * tx - qx * tz), vz + qw * tz + (qx * ty - qy * tx)
	end
	-- Ry(yaw) * Rx(pitch) * Rz(roll)
	local function qeuler(p, y, r)
		local ax, ay, az, aw = qaxis(0, 1, 0, y)
		local bx, by, bz, bw = qaxis(1, 0, 0, p)
		ax, ay, az, aw = qmul(ax, ay, az, aw, bx, by, bz, bw)
		bx, by, bz, bw = qaxis(0, 0, 1, r)
		return qmul(ax, ay, az, aw, bx, by, bz, bw)
	end

	local function clamp(x, a, b) if x < a then return a elseif x > b then return b end return x end
	local function smooth(x) x = clamp(x, 0, 1) return x * x * (3 - 2 * x) end
	local function lerp(a, b, k) return a + (b - a) * k end
	local function hash(x) local s = sin(x * 12.9898 + 4.1414) * 43758.5453 return s - floor(s) end
	-- -1..1: holds, then jerks to a new random value (rate = jerks per second)
	local function twitch(time, rate, seed)
		local u = time * rate + seed * 3.7
		local k = floor(u)
		local a0 = hash(k + seed) * 2 - 1
		local a1 = hash(k + 1 + seed) * 2 - 1
		if hash(k * 1.3 + seed) < 0.45 then a1 = a0 end
		return lerp(a0, a1, smooth((u - k) * 6 - 5))
	end
	-- -1..1 smooth noise
	local function wobble(time, rate, seed)
		local u = time * rate + seed * 1.37
		local k = floor(u)
		return lerp(hash(k + seed) * 2 - 1, hash(k + 1 + seed) * 2 - 1, smooth(u - k))
	end
	-- piecewise ease between keys {t0, v0, t1, v1, ...}
	local function keyed(t, k)
		if t <= k[1] then return k[2] end
		for i = 3, #k, 2 do
			if t <= k[i] then return lerp(k[i - 1], k[i + 1], smooth((t - k[i - 2]) / (k[i] - k[i - 2]))) end
		end
		return k[#k]
	end

	-- ---------------------------------------------------------------- rig cache
	local C = nil
	local function rig()
		if C then return C end
		if type(WH_RIG) ~= "table" or type(WH_RIG.parts) ~= "table" then return nil end
		local c = {n = #WH_RIG.parts, name = {}, idx = {}, par = {}, px = {}, py = {}, pz = {}, dx = {}, dy = {}, dz = {},
			ep = {}, ey = {}, er = {}, wx = {}, wy = {}, wz = {}, ww = {}, qx = {}, qy = {}, qz = {}, qw = {},
			ppx = {}, ppy = {}, ppz = {}, cx = {}, cy = {}, cz = {}}
		for i, p in ipairs(WH_RIG.parts) do c.name[i] = p.name; c.idx[p.name] = i end
		for i, p in ipairs(WH_RIG.parts) do
			c.par[i] = p.parent and c.idx[p.parent] or 0
			c.px[i], c.py[i], c.pz[i] = p.pivot[1], p.pivot[2], p.pivot[3]
			c.dx[i], c.dy[i], c.dz[i] = p.center[1] - p.pivot[1], p.center[2] - p.pivot[2], p.center[3] - p.pivot[3]
		end
		C = c
		return c
	end

	local G = {p = 0, y = 0, r = 0, ox = 0, oy = 0, oz = 0}      -- whole-body rotation (about GP) + move
	local GP = {0, 1.15, 0}
	local function reset(c)
		for i = 1, c.n do c.ep[i], c.ey[i], c.er[i] = 0, 0, 0 end
		G.p, G.y, G.r, G.ox, G.oy, G.oz = 0, 0, 0, 0, 0, 0
	end
	local function E(c, i, w, p, y, r)
		if not i then return end
		c.ep[i] = c.ep[i] + w * (p or 0)
		c.ey[i] = c.ey[i] + w * (y or 0)
		c.er[i] = c.er[i] + w * (r or 0)
	end
	local function glob(w, p, y, r, ox, oy, oz)
		G.p, G.y, G.r = G.p + w * p, G.y + w * y, G.r + w * r
		G.ox, G.oy, G.oz = G.ox + w * ox, G.oy + w * oy, G.oz + w * oz
	end

	local function solve(c)
		for i = 1, c.n do
			local lx, ly, lz, lw = qeuler(c.ep[i], c.ey[i], c.er[i])
			local p = c.par[i]
			if p == 0 then
				c.wx[i], c.wy[i], c.wz[i], c.ww[i] = lx, ly, lz, lw
				c.ppx[i], c.ppy[i], c.ppz[i] = c.px[i], c.py[i], c.pz[i]
			else
				local Px, Py, Pz, Pw = c.wx[p], c.wy[p], c.wz[p], c.ww[p]
				c.wx[i], c.wy[i], c.wz[i], c.ww[i] = qmul(Px, Py, Pz, Pw, lx, ly, lz, lw)
				local vx, vy, vz = qrot(Px, Py, Pz, Pw, c.px[i] - c.px[p], c.py[i] - c.py[p], c.pz[i] - c.pz[p])
				c.ppx[i], c.ppy[i], c.ppz[i] = c.ppx[p] + vx, c.ppy[p] + vy, c.ppz[p] + vz
			end
			local vx, vy, vz = qrot(c.wx[i], c.wy[i], c.wz[i], c.ww[i], c.dx[i], c.dy[i], c.dz[i])
			c.cx[i], c.cy[i], c.cz[i] = c.ppx[i] + vx, c.ppy[i] + vy, c.ppz[i] + vz
		end
		local gx, gy, gz, gw = qeuler(G.p, G.y, G.r)
		for i = 1, c.n do
			local vx, vy, vz = qrot(gx, gy, gz, gw, c.cx[i] - GP[1], c.cy[i] - GP[2], c.cz[i] - GP[3])
			c.cx[i], c.cy[i], c.cz[i] = GP[1] + vx + G.ox, GP[2] + vy + G.oy, GP[3] + vz + G.oz
			c.qx[i], c.qy[i], c.qz[i], c.qw[i] = qmul(gx, gy, gz, gw, c.wx[i], c.wy[i], c.wz[i], c.ww[i])
		end
	end

	-- ---------------------------------------------------------------- the poses (each adds its angles * w)
	-- float: hovering, hunched, head jutting forward; arms in the ghost pose (forearms raised, hands dangling) and
	-- drifting; robe and hair swaying in waves. Moving: she leans into the velocity, banks into side moves, the robe
	-- and hair stream behind, the arms sweep back.
	local function float(c, I, a, w)
		local T, sd = a.time, a.seed
		local F = WV_ANIM.flySpeed
		local kf = clamp(a.vf / F, -1, 1)
		local ks = clamp(a.vs / F, -1, 1)
		local ku = clamp(a.vu / F, -1, 1)
		local k = clamp(sqrt(a.vf * a.vf + a.vs * a.vs + 0.5 * a.vu * a.vu) / F, 0, 1)
		local kb = clamp(-kf, 0, 1)                                     -- (backing away)
		local bob = 0.05 * sin(T * 1.6 + sd) + 0.02 * sin(T * 2.9 + sd * 2)
		glob(w, 24 * clamp(kf, 0, 1) - 14 * kb - 10 * ku, 0, -18 * ks + 2 * sin(T * 0.7 + sd), 0, bob, 0)
		local hunch = 12 + 3 * sin(T * 0.9 + sd)
		E(c, I.torso, w, hunch, 4 * wobble(T, 0.4, sd), 3 * sin(T * 0.7 + sd))
		-- head jutting forward, slowly tilting; now and then a sharp jerk (unnatural, creepy)
		local lk = clamp((a.look or 0) / RAD, -50, 50)
		E(c, I.neck, w, 26 - 6 * k - lk * 0.3, 0, 0)
		E(c, I.head, w, -26 - lk * 0.5 + 6 * twitch(T, 0.35, sd + 1),
			12 * twitch(T, 0.45, sd + 2), 10 * sin(T * 0.5 + sd) + 16 * twitch(T, 0.3, sd + 5))
		E(c, I.jaw, w, 10 + 6 * sin(T * 0.8 + sd) + 8 * k, 0, 0)
		-- hair: hangs (counters the body's pitch), sways, streams back with speed
		local bodyP = 24 * clamp(kf, 0, 1) + hunch                   -- (+ neck + head pitch cancel: ~0)
		E(c, I.hair, w, -bodyP * 0.8 + 6 * sin(T * 1.1 + sd) + 50 * k, 0, 6 * sin(T * 0.8 + sd + 1) - 30 * ks)
		-- robe: a wave down the skirt; streaming behind when moving
		E(c, I.robe_up, w, -hunch * 0.6 + 3 * sin(T * 1.1 + sd) + 6 * k, 0, 3 * sin(T * 0.9 + sd))
		E(c, I.robe_mid, w, 5 * sin(T * 1.1 + sd - 0.8) + 18 * k - 16 * kb, 0, 4 * sin(T * 0.9 + sd - 0.8) - 16 * ks)
		E(c, I.robe_low, w, 7 * sin(T * 1.1 + sd - 1.6) + 22 * k - 20 * kb, 0, 6 * sin(T * 0.9 + sd - 1.6) - 18 * ks)
		-- arms: the ghost pose (upper arms forward, forearms raised, wrists limp) <-> swept back in flight
		for s = -1, 1, 2 do
			local up, low, hand = (s > 0) and I.arm_l_up or I.arm_r_up, (s > 0) and I.arm_l_low or I.arm_r_low,
				(s > 0) and I.hand_l or I.hand_r
			local d = 5 * sin(T * 0.7 + sd + s)
			local ghostUp, ghostLow, ghostHand = -38 - hunch + d, -62 + 4 * sin(T * 0.9 + s), 92 + 6 * sin(T * 1.3 + s * 2)
			local flyUp, flyLow, flyHand = 38, 10, 20
			E(c, up, w, lerp(ghostUp, flyUp, k), lerp(-6, 0, k) * s, lerp(-10, 12, k) * s)
			E(c, low, w, lerp(ghostLow, flyLow, k), lerp(8, 0, k) * s, 0)
			E(c, hand, w, lerp(ghostHand, flyHand, k), 0, lerp(-6, 0, k) * s)
		end
	end

	-- attack: rears back with the striking arm high (shrieking: head up, jaw wide), then lunges and rakes the claw
	-- down across, then recovers to the float pose by WV_ANIM.attack
	local K_ARM = {0, -38, 0.14, -165, 0.24, -55, 0.32, -40, 0.5, -38}
	local K_LOW = {0, -62, 0.14, -55, 0.22, -15, 0.32, -30, 0.5, -62}
	local K_HAND = {0, 92, 0.14, 40, 0.24, -25, 0.32, 20, 0.5, 92}
	local K_YAW = {0, 0, 0.14, 25, 0.26, -25, 0.5, 0}           -- the arm's sweep across (toward her other side)
	local K_ROLL = {0, -10, 0.14, 30, 0.26, -10, 0.5, -10}
	local K_TOR = {0, 12, 0.14, -12, 0.24, 30, 0.34, 18, 0.5, 12}
	local K_TWIST = {0, 0, 0.14, 22, 0.26, -18, 0.5, 0}         -- torso yaw toward the striking side, then through
	local K_LUNGE = {0, 0, 0.12, -0.12, 0.24, 0.55, 0.36, 0.3, 0.5, 0}
	local K_HEAD = {0, -26, 0.14, -55, 0.24, -52, 0.36, -40, 0.5, -26}   -- (up: her face toward the victim while lunging)
	local K_JAW = {0, 10, 0.1, 42, 0.3, 48, 0.42, 30, 0.5, 12}
	local K_OFF = {0, -38, 0.14, -10, 0.26, 35, 0.5, -38}      -- the other arm: flung back / out for balance
	local function attack(c, I, a, w)
		local t, T, sd = a.ta or 0, a.time, a.seed
		local s = (a.side or -1) > 0 and 1 or -1
		local up, low, hand = (s > 0) and I.arm_l_up or I.arm_r_up, (s > 0) and I.arm_l_low or I.arm_r_low,
			(s > 0) and I.hand_l or I.hand_r
		local oup, olow, ohand = (s > 0) and I.arm_r_up or I.arm_l_up, (s > 0) and I.arm_r_low or I.arm_l_low,
			(s > 0) and I.hand_r or I.hand_l
		local tor = keyed(t, K_TOR)
		glob(w, 8, 0, 0, 0, 0.04 * sin(T * 1.6 + sd), keyed(t, K_LUNGE))
		E(c, I.torso, w, tor, s * keyed(t, K_TWIST), 0)
		E(c, I.neck, w, 22, -s * keyed(t, K_TWIST) * 0.5, 0)
		E(c, I.head, w, keyed(t, K_HEAD), 0, 6 * sin(T * 9))
		E(c, I.jaw, w, keyed(t, K_JAW), 0, 0)
		E(c, I.hair, w, -tor * 0.8 + 30 * smooth((t - 0.14) / 0.12) * (1 - smooth((t - 0.3) / 0.2)) + 8, 0, 0)
		E(c, I.robe_up, w, -tor * 0.5, 0, 0)
		E(c, I.robe_mid, w, 18 * smooth((t - 0.12) / 0.15) * (1 - smooth((t - 0.3) / 0.2)), 0, 0)
		E(c, I.robe_low, w, 26 * smooth((t - 0.14) / 0.15) * (1 - smooth((t - 0.32) / 0.18)), 0, 0)
		E(c, up, w, keyed(t, K_ARM) - tor, -s * keyed(t, K_YAW), s * keyed(t, K_ROLL))
		E(c, low, w, keyed(t, K_LOW), 0, 0)
		E(c, hand, w, keyed(t, K_HAND), 0, 0)
		E(c, oup, w, keyed(t, K_OFF) - tor, 0, -s * 18)
		E(c, olow, w, -40, 0, 0)
		E(c, ohand, w, 60, 0, 0)
	end

	-- stunned: arms thrown up crossed before the face, claws splayed; the head thrashes, the body convulses and
	-- shudders in the air, the jaw screams wide; held for as long as the pose lasts
	local function stunned(c, I, a, w)
		local t, T, sd = a.ts or 0, a.time, a.seed
		local rise = smooth(t / 0.25)                                 -- (the recoil comes in fast)
		local cv = twitch(T, 9, sd)                                   -- convulsions
		glob(w, -14 * rise + 7 * cv, 6 * twitch(T, 7, sd + 3), 6 * twitch(T, 8, sd + 4),
			0.025 * twitch(T, 13, sd + 6), 0.06 * rise + 0.025 * twitch(T, 11, sd + 7), -0.18 * rise + 0.025 * twitch(T, 12, sd + 8))
		E(c, I.torso, w, 24 * rise + 8 * cv, 10 * twitch(T, 6, sd + 9), 8 * twitch(T, 7, sd + 10))
		E(c, I.neck, w, 15, 20 * twitch(T, 5, sd + 11), 0)
		E(c, I.head, w, 10 + 25 * twitch(T, 4.5, sd + 12), 45 * twitch(T, 5.5, sd + 13), 30 * twitch(T, 6.5, sd + 14))
		E(c, I.jaw, w, 40 + 12 * twitch(T, 8, sd + 15), 0, 0)
		E(c, I.hair, w, -20 + 30 * twitch(T, 6, sd + 16), 0, 30 * twitch(T, 5, sd + 17))
		E(c, I.robe_up, w, -10 + 8 * cv, 0, 10 * twitch(T, 7, sd + 18))
		E(c, I.robe_mid, w, 15 * twitch(T, 6, sd + 19), 0, 15 * twitch(T, 5, sd + 20))
		E(c, I.robe_low, w, 20 * twitch(T, 7, sd + 21), 0, 20 * twitch(T, 6, sd + 22))
		for s = -1, 1, 2 do
			local up, low, hand = (s > 0) and I.arm_l_up or I.arm_r_up, (s > 0) and I.arm_l_low or I.arm_r_low,
				(s > 0) and I.hand_l or I.hand_r
			local j = 10 * twitch(T, 8, sd + 23 + s)
			-- (upper arm forward to about horizontal - minus the torso's recoil hunch - elbows in; the forearm up across
			--  the face, toward the other side; the claws splayed, trembling)
			E(c, up, w, (-80 + j) * rise + (-38) * (1 - rise), -10 * s * rise, -18 * s * rise)
			E(c, low, w, (-80 + j) * rise - 62 * (1 - rise), -28 * s * rise, 0)
			E(c, hand, w, -10 + 20 * twitch(T, 9, sd + 25 + s), 0, 25 * s * twitch(T, 7, sd + 27 + s))
		end
	end

	function WVPose(a, out)
		local c = rig()
		if not c then return out end
		reset(c)
		local I = c.idx
		local wf, wa, ws = a.wf or 1, a.wa or 0, a.ws or 0
		local sum = wf + wa + ws
		if sum < 1e-6 then wf, sum = 1, 1 end
		wf, wa, ws = wf / sum, wa / sum, ws / sum
		local A = a
		if A.time == nil then A.time = 0 end
		if A.seed == nil then A.seed = 0 end
		if A.vf == nil then A.vf, A.vs, A.vu = 0, 0, 0 end
		if wf > 1e-4 then float(c, I, A, wf) end
		if wa > 1e-4 then attack(c, I, A, wa) end
		if ws > 1e-4 then stunned(c, I, A, ws) end
		G.oy = G.oy + WV_ANIM.lift
		solve(c)
		for i = 1, c.n do
			local nm = c.name[i]
			local tr = out[nm]
			if tr and tr.pos and tr.rot then
				local p, q = tr.pos, tr.rot
				p[1], p[2], p[3] = c.cx[i], c.cy[i], c.cz[i]
				q[1], q[2], q[3], q[4] = c.qx[i], c.qy[i], c.qz[i], c.qw[i]
			else
				out[nm] = Transform(Vec(c.cx[i], c.cy[i], c.cz[i]), Quat(c.qx[i], c.qy[i], c.qz[i], c.qw[i]))
			end
		end
		return out
	end
end

-- ======================================================================== the models on this machine
local WVS = {}              -- [player] = model

local function wvRebuildShapes()
	WV_SHAPES = {}
	for _, MV in pairs(WVS) do
		for _, q in ipairs(MV.parts or {}) do
			for _, s in ipairs(q.shapes) do WV_SHAPES[#WV_SHAPES + 1] = s end
		end
	end
end

local function wvSpawnPart(file)
	local ok, ents = pcall(Spawn, string.format("<body dynamic='true' tags='whwitch'><vox tags='whwitch unbreakable nocull' file='%s' scale='%.3f'/></body>",
		file, WV_VOX_SCALE), Transform(Vec(0, -400, 0)))
	if not ok or type(ents) ~= "table" then return nil, {} end
	local body = nil
	for _, h in ipairs(ents) do if GetEntityType(h) == "body" and not body then body = h end end
	if not body then return nil, {} end
	local shapes = GetBodyShapes(body) or {}
	for _, s in ipairs(shapes) do SetShapeCollisionFilter(s, WV_LAYER, 0) end
	return body, shapes
end

-- each part's voxel box centred on its body origin (the rig places the body at the box centre); measured once the
-- engine reports the size (a fresh shape can read 0 in its spawn frame). HvC's mvCentre (verified in-game).
local function wvCentre(q)
	if q.centred then return true end
	for _, sh in ipairs(q.shapes) do
		if not IsHandleValid(sh) then return false end
		local x, y, z, vs = GetShapeSize(sh)
		if not x or x <= 0 or not vs or vs <= 0 then return false end
	end
	for _, sh in ipairs(q.shapes) do
		local t = GetShapeLocalTransform(sh)
		local x, y, z, vs = GetShapeSize(sh)
		local c = TransformToParentPoint(t, Vec(x * vs / 2, y * vs / 2, z * vs / 2))
		SetShapeLocalTransform(sh, Transform(VecSub(t.pos, c), t.rot))
	end
	q.centred = true
	return true
end

local function wvNew(p)
	return {p = p, parts = nil, byName = {}, out = {}, pose = "float", lastT = 0, born = GetTime(), wisp = 0, emitT = -1,
		hidden = {}, fpWas = false,
		a = {wf = 1, wa = 0, ws = 0, ta = 0, ts = 0, side = 1, vf = 0, vs = 0, vu = 0, look = 0, time = 0, seed = (p * 7) % 97}}
end

local function wvSpawn(MV)
	MV.parts, MV.byName, MV.hidden = {}, {}, {}
	for _, pt in ipairs(WH_RIG.parts) do
		local body, shapes = wvSpawnPart(pt.file)
		if body then
			local q = {name = pt.name, body = body, shapes = shapes, rest = Transform(Vec(pt.center[1], pt.center[2], pt.center[3]), Quat()),
				center = pt.center}
			MV.parts[#MV.parts + 1] = q
			MV.byName[pt.name] = q
		end
	end
	wvRebuildShapes()
end

local function wvDelete(MV)
	for _, q in ipairs(MV.parts or {}) do
		if IsHandleValid(q.body) then Delete(q.body) end
	end
	MV.parts = nil
end

-- player p's model parts on this machine (body handles; {} without a model): her own pings pass through them
function whVisualBodies(p)
	local l = {}
	for _, q in ipairs(WVS[p] and WVS[p].parts or {}) do
		if IsHandleValid(q.body) then l[#l + 1] = q.body end
	end
	return l
end

function whVisualClear()
	for _, MV in pairs(WVS) do wvDelete(MV) end
	WVS = {}
	WV_SHAPES = {}
end

-- show / hide one part on this machine (tags only change when the state does)
local function wvSetHidden(MV, q, hide)
	if MV.hidden[q.name] == hide then return end
	MV.hidden[q.name] = hide
	for _, s in ipairs(q.shapes) do
		if IsHandleValid(s) then if hide then SetTag(s, "invisible") else RemoveTag(s, "invisible") end end
	end
end

local function approach(x, target, step)
	if x < target then return math.min(target, x + step) end
	return math.max(target, x - step)
end

local function rnd(a, b) return a + (b - a) * math.random() end

-- wisps peeling off the hem, the sleeves and the hair, drifting up and behind
local WISP_FROM = {"robe_low", "robe_low", "robe_mid", "hand_l", "hand_r", "hair"}
local function wvWisps(MV, root, vel, n)
	ParticleReset()
	ParticleType("plain")
	ParticleColor(0.85, 0.92, 1.0, 0.55, 0.68, 0.85)
	ParticleRadius(0.05, 0.22, "easeout")
	ParticleAlpha(0.32, 0.0)
	ParticleGravity(0.6)
	ParticleDrag(0.4)
	ParticleEmissive(0.8, 0.0)
	ParticleCollide(0)
	for _ = 1, n do
		local name = WISP_FROM[math.random(1, #WISP_FROM)]
		local tr = MV.out[name]
		if tr then
			local lp = Vec(tr.pos[1] + rnd(-0.18, 0.18), tr.pos[2] + rnd(-0.25, 0.05), tr.pos[3] + rnd(-0.15, 0.1))
			local wp = TransformToParentPoint(root, lp)
			local v = Vec(-vel[1] * 0.3 + rnd(-0.25, 0.25), -vel[2] * 0.3 + rnd(0.05, 0.35), -vel[3] * 0.3 + rnd(-0.25, 0.25))
			SpawnParticle(wp, v, rnd(0.7, 1.5))
		end
	end
end

-- her own machine, during the strike: the striking forearm + claw sweep across the view (camera space)
local function wvClawsInView(MV, side, t)
	local cam = GetCameraTransform()
	local u = t / WV_ANIM.attack
	local k = u < 0.28 and 0 or (u > 0.6 and 1 or (u - 0.28) / 0.32)
	k = k * k * (3 - 2 * k)
	local lift = u < 0.28 and u / 0.28 or 1
	local hx = (-0.34 + 0.62 * k) * side                     -- (her left claw comes in from the left of the view)
	local pos = Vec(hx, -0.45 + 0.6 * lift - 0.55 * k, -0.62 - 0.1 * k)
	local rot = QuatEuler(80 - 40 * k, 0, (25 - 70 * k) * side)   -- (claws pointing into the view, turning as it rakes)
	local hand = MV.byName[side > 0 and "hand_l" or "hand_r"]
	local low = MV.byName[side > 0 and "arm_l_low" or "arm_r_low"]
	local tH = TransformToParentTransform(cam, Transform(pos, rot))
	local zero = Vec(0, 0, 0)
	if hand and IsHandleValid(hand.body) then
		SetBodyTransform(hand.body, tH)
		SetBodyVelocity(hand.body, zero); SetBodyAngularVelocity(hand.body, zero)
		wvSetHidden(MV, hand, not hand.centred)
	end
	if low and hand and IsHandleValid(low.body) then
		local d = Vec(low.center[1] - hand.center[1], low.center[2] - hand.center[2], low.center[3] - hand.center[3])
		SetBodyTransform(low.body, TransformToParentTransform(tH, Transform(d, Quat())))
		SetBodyVelocity(low.body, zero); SetBodyAngularVelocity(low.body, zero)
		wvSetHidden(MV, low, not low.centred)
	end
end

local function wvTickOne(MV, e, dt)
	local p = MV.p
	if MV.parts then                                     -- (a part deleted under us, e.g. a reload: spawn anew)
		for _, q in ipairs(MV.parts) do
			if not IsHandleValid(q.body) then wvDelete(MV); wvRebuildShapes(); break end
		end
	end
	if not MV.parts then wvSpawn(MV) end
	local now = GetTime()
	local a = MV.a
	-- pose state + blend weights
	local pose, t = e.pose, tonumber(e.t) or 0
	if pose ~= "attack" and pose ~= "stunned" then pose = "float" end
	if pose == "attack" and (MV.pose ~= "attack" or t < MV.lastT - 1e-3) then a.side = -a.side end   -- (a new strike)
	MV.pose, MV.lastT = pose, t
	local tf, ta, ts = 0, 0, 0
	if pose == "attack" and t < WV_ANIM.attack then ta = 1
	elseif pose == "stunned" then ts = 1
	else tf = 1 end
	local step = dt / ((ta > 0) and WV_ANIM.blendAttack or WV_ANIM.blendIn)
	a.wf, a.wa, a.ws = approach(a.wf, tf, step), approach(a.wa, ta, step), approach(a.ws, ts, step)
	if pose == "attack" then a.ta = math.min(t, WV_ANIM.attack) end
	if pose == "stunned" then a.ts = t end
	-- velocity in her frame (smoothed) and where she looks
	local tr = GetPlayerTransform(p)
	local root = Transform(tr.pos, QuatRotateQuat(tr.rot, QuatEuler(0, 180, 0)))   -- (the rig's +z = the player's -z)
	local vel = GetPlayerVelocity(p)
	local lv = TransformToLocalVec(root, vel)
	local ks = (dt > 0) and (1 - math.exp(-dt / WV_ANIM.velSmooth)) or 0
	a.vf = a.vf + (lv[3] - a.vf) * ks
	a.vs = a.vs + (lv[1] - a.vs) * ks
	a.vu = a.vu + (lv[2] - a.vu) * ks
	local eye = GetPlayerEyeTransform(p)
	local fwd = QuatRotateVec(eye.rot, Vec(0, 0, -1))
	a.look = math.asin(math.max(-1, math.min(1, fwd[2])))
	a.time = now
	local ok = pcall(WVPose, a, MV.out)
	if not ok then return end
	-- place the parts
	-- (her own machine in first person: hidden; the camera isn't locked - the user - so in third person she sees herself)
	local isLocal = (p == GetLocalPlayer()) and not GetBool("game.thirdperson")
	local fp = isLocal and pose == "attack" and t < WV_ANIM.attack
	local zero = Vec(0, 0, 0)
	for _, q in ipairs(MV.parts) do
		local centred = wvCentre(q)
		local inView = fp and (q.name == "hand_l" or q.name == "arm_l_low") and a.side > 0
			or fp and (q.name == "hand_r" or q.name == "arm_r_low") and a.side < 0
		if not inView then
			wvSetHidden(MV, q, isLocal or not centred)
			if IsHandleValid(q.body) then
				SetBodyTransform(q.body, TransformToParentTransform(root, MV.out[q.name] or q.rest))
				SetBodyVelocity(q.body, zero)
				SetBodyAngularVelocity(q.body, zero)
			end
		end
	end
	if fp then wvClawsInView(MV, a.side, t) end
	-- glow: the faint self-glow flickers (strobes when stunned), brighter for a moment when she appears; a cold light
	local age = now - MV.born
	if now - MV.emitT > 0.1 or age < 0.6 then
		MV.emitT = now
		local s = 0.85 + 0.25 * math.sin(now * 7.3 + a.seed) * math.sin(now * 2.1)
		if pose == "stunned" then s = (math.random() < 0.5) and 0.25 or 1.6 end
		if age < 0.6 then s = s + 2.5 * (1 - age / 0.6) end
		for _, q in ipairs(MV.parts) do
			for _, sh in ipairs(q.shapes) do if IsHandleValid(sh) then SetShapeEmissiveScale(sh, s) end end
		end
	end
	if p == GetLocalPlayer() then                              -- (her own soft glow lights what's around her at night - the user)
		local cam = GetCameraTransform()
		local ahead = TransformToParentPoint(cam, Vec(0, -0.3, -4))
		PointLight(VecAdd(GetPlayerTransform(p).pos, Vec(0, 1.4, 0)), 0.7, 0.82, 1.0, WV_ANIM.selfLight)
		PointLight(ahead, 0.7, 0.82, 1.0, WV_ANIM.selfLight * 0.6)
	end
	if isLocal then return end
	local torso = MV.out.torso
	local chest = TransformToParentPoint(root, Vec(0, (torso and torso.pos[2] or 1.3) + 0.1, 0.25))
	local li = WV_ANIM.light * (0.8 + 0.2 * math.sin(now * 5.1 + a.seed))
	if pose == "stunned" then li = li * (0.4 + 1.2 * math.random()) end
	PointLight(chest, 0.6, 0.8, 1.0, li)
	-- wisps (by distance to this machine's camera)
	local d = VecLength(VecSub(GetCameraTransform().pos, chest))
	local rate = WV_ANIM.wispRate
	if d > WV_ANIM.wispFar then rate = 0 elseif d > WV_ANIM.wispMid then rate = rate * 0.5 end
	MV.wisp = MV.wisp + rate * dt + (e.smoke and 0.5 or 0)
	local n = math.floor(MV.wisp)
	if n > 0 then
		MV.wisp = MV.wisp - n
		wvWisps(MV, root, vel, math.min(n, 8))
	end
end

-- spirits: list of {p = player, pose = "float" | "attack" | "stunned", t = seconds in this pose, smoke = bool}
function whVisualTick(dt, spirits)
	dt = tonumber(dt) or 0
	if dt < 0 then dt = 0 elseif dt > 0.1 then dt = 0.1 end
	if type(WH_RIG) ~= "table" then return end
	local live = {}
	if type(spirits) == "table" then
		for _, e in ipairs(spirits) do
			if type(e) == "table" and e.p and e.p ~= 0 and IsPlayerValid(e.p) and not live[e.p] then live[e.p] = e end
		end
	end
	local removed = false
	for p, MV in pairs(WVS) do                           -- (a spirit no more: its model goes)
		if not live[p] then wvDelete(MV); WVS[p] = nil; removed = true end
	end
	if removed then wvRebuildShapes() end
	for p, e in pairs(live) do
		if not WVS[p] then WVS[p] = wvNew(p) end
		wvTickOne(WVS[p], e, dt)
	end
end
